import {mountDirectionPicker} from './direction-picker.js';
import {rockHand,sourceGroups,removeRockPoint} from './rock-matching.js';
import {verifyRockScale} from './rock-scale.js';
function adaptInWorker(data){const worker=new Worker('./on-rock-worker.js',{type:'module'});return new Promise((resolve,reject)=>{const finish=(error,route)=>{clearTimeout(timer);worker.terminate();error?reject(Error(error)):resolve(route);};const timer=setTimeout(()=>finish('A análise demorou demais. Tente menos pegadas.'),45000);worker.onmessage=({data})=>finish(data.error,data.route);worker.onerror=()=>finish('Não foi possível abrir a análise. Confira a atualização do aplicativo.');worker.postMessage(data);});}
export function createOnRock({getWall,getFace=()=>null,processPhoto,onRoute}){
 const dialog=document.createElement('dialog');dialog.className='wide-dialog rock-dialog';
 dialog.innerHTML=`<button type="button" data-close>← Voltar</button><h2>On the Rock</h2><details><summary>Como fotografar e medir</summary><p>Fotografe uma face de frente, com a câmera perpendicular à superfície e sem inclinar o celular. Inclua duas marcas com distância medida entre elas, no mesmo plano das pegadas. Use uma referência longa e visível, sem precisar alcançar locais difíceis.</p><p>Distância da câmera, resolução e zoom podem mudar: marque a referência na própria foto usada aqui. Evite lente ultrawide, panoramas e fotos oblíquas. Uma referência de dois pontos ajusta a escala, mas não corrige perspectiva nem profundidade. Em tetos ou rocha com vários planos, trabalhe um plano por vez.</p><p>No muro de casa, cadastre a largura e a altura da área exata mostrada na foto, também tomada de frente. Inclinações, profundidade, atrito e posição do corpo ainda podem mudar o lance.</p></details><label>1. Foto da rocha<input data-photo type="file" accept="image/jpeg,image/png,image/webp"></label><label>Face de destino<select data-face></select></label><fieldset><legend>2. Escala da foto</legend><label>Modo<select data-scale-mode><option value="measured">Com distância medida</option><option value="fit">Sem medida: apenas proporções</option></select></label><div data-measured><div class="form-row"><label>Distância entre as marcas (m)<input data-meters type="number" min="0.01" max="30" step="0.01" value="1"></label><label>Reproduzir em (%)<input data-percent type="number" min="25" max="150" value="100"></label></div><button type="button" data-reference>Marcar as 2 pontas da referência</button><label>Segunda distância medida, C–D (m)<input data-check-meters type="number" min="0.01" max="30" step="0.01" value="1"></label><button type="button" data-check>Marcar C e D para conferir</button><p class="help">Meça outro trecho, de preferência em outra direção ou região do mesmo plano. Diferença acima de 10% pede revisão. Essa conferência não valida profundidade nem corrige perspectiva.</p><p data-check-status role="status"></p><p data-reference-status role="status">Referência não marcada.</p></div></fieldset><h3>3. Pegadas</h3><p class="help">Marque saída E, saída D, movimentos, final E e final D, nessa ordem. Indique a mão em cada movimento e a puxada por setas. Saídas e finais usam E e D. Para juntar mãos ou reutilizar a mesma pegada, selecione o ponto e toque em Repetir pegada.</p><label>Editar ponto<select data-point><option value="-1">Nova pegada</option></select></label><div class="form-row"><label>Qualidade<select data-quality><option value="unknown">Não sei</option><option value="good">Boa</option><option value="medium">Média</option><option value="bad">Ruim</option></select></label><label>Tipo<select data-type><option>Não informado</option><option>Batente</option><option>Reglete</option><option>Abaulado</option><option>Pinça</option><option>Buraco</option><option>Outro</option></select></label></div><label>Mão do movimento<select data-hand><option value="L">Esquerda</option><option value="R">Direita</option></select></label><div data-pull></div><div class="rock-photo"><canvas aria-label="Foto da rocha: referência e pegadas"></canvas></div><p data-status role="status">Escolha uma foto.</p><button type="button" data-new>+ Nova pegada</button><button type="button" data-repeat>Repetir pegada</button><button type="button" data-remove>Excluir ponto</button><button type="button" data-generate class="primary">Comparar com meu muro</button><p class="help">A revisão mostra as distâncias de referência e as encontradas no muro. Tipo e puxada são preferências de busca; confira se a agarra sugerida serve ao movimento. Pés e mãos juntas podem ser ajustados no editor.</p>`;
 document.body.append(dialog);const $=s=>dialog.querySelector(s),canvas=$('canvas'),ctx=canvas.getContext('2d');let photo=null,points=[],reference=[],verification=[],select=-1,mode='holds',token=0,newPull={direction:null,directionKnown:false,directionTolerance:100};
 function editPull(){const p=select>=0?points[select]:newPull;mountDirectionPicker($('[data-pull]'),{...p,direction:p.direction??180,directionKnown:p.directionKnown??Number.isFinite(p.direction)},()=>{const p=select>=0?points[select]:newPull,host=$('[data-pull]');p.directionKnown=host.querySelector('[name=directionKnown]').value==='true';p.direction=p.directionKnown?Number(host.querySelector('[name=direction]').value):null;p.directionTolerance=Number(host.querySelector('[name=directionTolerance]').value);refresh();});}
 function calibration(){return {a:reference[0],b:reference[1],meters:Number($('[data-meters]').value),percent:Number($('[data-percent]').value),check:{a:verification[0],b:verification[1],meters:Number($('[data-check-meters]').value)}};}
 function refresh(){
  $('[data-point]').replaceChildren(...[-1,...points.map((_,i)=>i)].map(i=>{const o=document.createElement('option');o.value=i;o.textContent=i<0?'Nova pegada':`${i+1} · ${i<2?'Saída':i>=points.length-2?'Final':'Mão'} ${rockHand(points,i)==='LH'?'E':'D'} · ${points[i].type}`;return o;}));$('[data-point]').value=select;
  ctx.clearRect(0,0,canvas.width,canvas.height);if(photo)ctx.drawImage(photo,0,0,canvas.width,canvas.height);
  for(const [list,color]of [[reference,'#7ed9ea'],[verification,'#dd91ff'],[points,'#ff8a36']])list.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,12,0,Math.PI*2);ctx.fillStyle=list===points&&i===select?'#fff36a':color;ctx.fill();ctx.fillStyle='#000';ctx.font='bold 15px Arial';ctx.textAlign='center';ctx.fillText(list===reference?['A','B'][i]:list===verification?['C','D'][i]:i+1,p.x*canvas.width,p.y*canvas.height+5);if(list===points&&Number.isFinite(p.direction)&&p.directionTolerance!==180){const angle=p.direction*Math.PI/180;ctx.beginPath();ctx.moveTo(p.x*canvas.width,p.y*canvas.height);ctx.lineTo(p.x*canvas.width+Math.sin(angle)*30,p.y*canvas.height-Math.cos(angle)*30);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke();const ex=p.x*canvas.width+Math.sin(angle)*30,ey=p.y*canvas.height-Math.cos(angle)*30;ctx.beginPath();ctx.moveTo(ex-Math.sin(angle-.5)*10,ey+Math.cos(angle-.5)*10);ctx.lineTo(ex,ey);ctx.lineTo(ex-Math.sin(angle+.5)*10,ey+Math.cos(angle+.5)*10);ctx.stroke();}});
  $('[data-check-status]').textContent=verification.length+'/2 marcas de conferência';if(photo&&reference.length===2&&verification.length===2){try{const result=verifyRockScale(photo.width/photo.height,calibration());$('[data-check-status]').textContent=`Diferença: ${(result.error*100).toFixed(1)}% · ${result.valid?'medidas compatíveis':'revise a foto ou as medidas'}`;}catch(e){$('[data-check-status]').textContent=e.message;}}
  $('[data-reference-status]').textContent=reference.length===2?'Referência A–B marcada.':`${reference.length}/2 marcas da referência`;
  $('[data-status]').textContent=mode==='check'?'Toque em C e D, nas pontas da segunda medida.':mode==='reference'?'Toque nas duas pontas da distância medida.':`${points.length} pegadas · ${select<0?'toque para adicionar':`editando ${select+1}`}`;
  $('[data-repeat]').disabled=select<0||points.length>=20;
  $('[data-hand]').disabled=select>=0&&(select<2||select>=points.length-2);
  if(select>=0)$('[data-hand]').value=rockHand(points,select)==='LH'?'L':'R';
  $('[data-generate]').disabled=!photo||points.length<4||($('[data-scale-mode]').value==='measured'&&(reference.length!==2||verification.length!==2));
 }
 function choose(i){select=i;mode='holds';if(i>=0){$('[data-quality]').value=points[i].quality;$('[data-type]').value=points[i].type;}else $('[data-hand]').value=points.length%2?'R':'L';editPull();refresh();}
 $('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>token++;
 $('[data-photo]').onchange=async e=>{const current=++token;photo=null;points=[];reference=[];verification=[];select=-1;newPull={direction:null,directionKnown:false,directionTolerance:100};editPull();refresh();try{const result=await processPhoto(e.target.files[0]),image=new Image();image.src=result.photo;await image.decode();if(current!==token)return;photo=image;const scale=Math.min(1,1200/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);refresh();}catch(error){if(current===token)$('[data-status]').textContent=error.message;}};
 $('[data-scale-mode]').onchange=()=>{$('[data-measured]').hidden=$('[data-scale-mode]').value!=='measured';mode='holds';refresh();};
 $('[data-reference]').onclick=()=>{if(!photo)return;reference=[];mode='reference';refresh();};
 $('[data-check]').onclick=()=>{if(!photo)return;verification=[];mode='check';refresh();};for(const name of ['meters','check-meters'])$(`[data-${name}]`).oninput=refresh;
 canvas.onclick=e=>{if(!photo)return;const r=canvas.getBoundingClientRect(),p={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};if(mode==='check'){verification.push(p);if(verification.length===2)mode='holds';refresh();return;}if(mode==='reference'){reference.push(p);if(reference.length===2)mode='holds';refresh();return;}const hit=points.findIndex(q=>Math.hypot((p.x-q.x)*r.width,(p.y-q.y)*r.height)<15);if(hit>=0){choose(hit);return;}if(select>=0){const groups=sourceGroups(points);points=points.map((q,i)=>groups[i]===groups[select]?{...q,...p}:q);refresh();return;}if(points.length>=20){$('[data-status]').textContent='Limite de 20 pegadas.';return;}points.push({...p,quality:$('[data-quality]').value,type:$('[data-type]').value,...newPull,hand:$('[data-hand]').value});$('[data-hand]').value=points.length%2?'R':'L';refresh();};
 $('[data-point]').onchange=e=>choose(Number(e.target.value));$('[data-new]').onclick=()=>choose(-1);
 for(const name of ['quality','type','hand'])$(`[data-${name}]`).onchange=()=>{if(select>=0){points[select][name]=$(`[data-${name}]`).value;refresh();}};
 $('[data-repeat]').onclick=()=>{if(select<0||points.length>=20)return;const original=points[select];points.push({...original,sameAs:select,hand:points.length%2?'R':'L'});choose(points.length-1);};
 $('[data-remove]').onclick=()=>{points=removeRockPoint(points,select>=0?select:points.length-1);choose(-1);};
  $('[data-generate]').onclick=async()=>{const current=token,button=$('[data-generate]'),controls=[...dialog.querySelectorAll('input,select,button:not([data-close])')].map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);canvas.style.pointerEvents='none';let errorText='';button.disabled=true;button.textContent='Comparando movimentos…';try{const measured=$('[data-scale-mode]').value==='measured'?calibration():null;const route=await adaptInWorker({wall:getWall(),faceId:$('[data-face]').value,points,aspect:photo.width/photo.height,calibration:measured});if(current!==token||!dialog.open)return;if(route.notes.length>2000)route.notes=route.notes.slice(0,2000);dialog.close();onRoute(route);}catch(error){errorText=error.message;}finally{button.textContent='Comparar com meu muro';if(current===token){canvas.style.pointerEvents='';controls.forEach(([el,disabled])=>el.disabled=disabled);if(dialog.open){refresh();if(errorText)$('[data-status]').textContent=errorText;}}}};
 return {open(){token++;canvas.style.pointerEvents='';dialog.querySelectorAll('input,select,button').forEach(el=>el.disabled=false);const wall=getWall();$('[data-face]').replaceChildren(...wall.faces.map(f=>{const o=document.createElement('option');o.value=f.id;o.textContent=f.name;return o;}));if(wall.faces.some(f=>f.id===getFace()))$('[data-face]').value=getFace();photo=null;points=[];reference=[];verification=[];select=-1;mode='holds';$('[data-photo]').value='';newPull={direction:null,directionKnown:false,directionTolerance:100};choose(-1);dialog.showModal();}};
}
